package io.github.weimanmk.easygot;
import android.content.Context;
import android.graphics.*;
import android.graphics.pdf.PdfDocument;
import android.text.*;
import org.json.*;
import java.io.*;
/** System PDF renderer. Question identity, numbering and learning state are owned by Rust. */
final class PaperPrinter {
    private final PdfDocument document=new PdfDocument();private PdfDocument.Page page;private Canvas canvas;private float y;private int pageNumber=0;private final String title,paperId;private final boolean answers;
    private PaperPrinter(JSONObject spec){title=spec.optString("title","EasyGot试卷");paperId=spec.optString("paperId");answers=spec.optBoolean("answers");}
    private void newPage(){if(page!=null)document.finishPage(page);page=document.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageNumber).create());canvas=page.getCanvas();canvas.drawColor(Color.WHITE);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.DKGRAY);paint.setTextSize(9);canvas.drawText("EasyGot  |  卷号 "+paperId+"  |  第 "+pageNumber+" 页",36,817,paint);paint.setTextSize(15);paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));canvas.drawText(title+(answers?" · 答案与解析":""),36,40,paint);paint.setColor(0xFF999999);canvas.drawLine(36,50,559,50,paint);y=66;}
    private void text(String text,int size){TextPaint paint=new TextPaint(Paint.ANTI_ALIAS_FLAG);paint.setTextSize(size);paint.setColor(Color.BLACK);StaticLayout layout=StaticLayout.Builder.obtain(text,0,text.length(),paint,523).setLineSpacing(3,1).setIncludePad(false).build();int start=0;while(start<layout.getLineCount()){if(y>775)newPage();int end=start;float origin=layout.getLineTop(start);while(end<layout.getLineCount()&&layout.getLineBottom(end)-origin<=790-y)end++;if(end==start){newPage();continue;}float height=layout.getLineBottom(end-1)-origin;canvas.save();canvas.clipRect(36,y,559,y+height);canvas.translate(36,y-origin);layout.draw(canvas);canvas.restore();y+=height+8;start=end;if(start<layout.getLineCount())newPage();}}
    private void space(int lines){Paint paint=new Paint();paint.setColor(0xFFDDDDDD);for(int i=0;i<lines;i++){if(y+24>790)newPage();canvas.drawLine(36,y+20,559,y+20,paint);y+=25;}y+=12;}
    static String create(Context context,String payload)throws Exception{JSONObject spec=new JSONObject(payload);PaperPrinter printer=new PaperPrinter(spec);File file;try{printer.newPage();printer.text("姓名：________________    日期：________________",10);printer.text("开始时间：________  结束时间：________  用时：________",10);printer.text("保留题号后作答，拍照时请包含卷号和题号。系统计时从App内点击开始纸上作答时计算。",9);JSONArray questions=spec.getJSONArray("questions");for(int i=0;i<questions.length();i++){JSONObject question=questions.getJSONObject(i);if(printer.y>670)printer.newPage();printer.text(question.getString("text"),12);String image=question.optString("image");if(image.matches("[a-f0-9]{64}")){File source=new File(context.getFilesDir(),"assets/"+image);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(source.getAbsolutePath(),bounds);bounds.inSampleSize=Math.max(1,Math.max(bounds.outWidth,bounds.outHeight)/1800);bounds.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeFile(source.getAbsolutePath(),bounds);if(bitmap!=null){float width=Math.min(480,bitmap.getWidth()),height=bitmap.getHeight()*width/bitmap.getWidth();if(height>300){width*=300/height;height=300;}if(printer.y+height>785)printer.newPage();printer.canvas.drawBitmap(bitmap,null,new RectF(36,printer.y,36+width,printer.y+height),new Paint(Paint.FILTER_BITMAP_FLAG));printer.y+=height+10;bitmap.recycle();}}printer.space(question.optInt("answerLines",2));}printer.document.finishPage(printer.page);printer.page=null;File dir=new File(context.getFilesDir(),"papers");dir.mkdirs();file=new File(dir,spec.getString("paperId")+(spec.optBoolean("answers")?"-answers":"-questions")+".pdf");if(!file.getCanonicalPath().startsWith(dir.getCanonicalPath()+"/"))throw new IOException("非法卷号");try(OutputStream out=new FileOutputStream(file)){printer.document.writeTo(out);}}finally{if(printer.page!=null)printer.document.finishPage(printer.page);printer.document.close();}return file.getAbsolutePath();}
}
